from audit_candidate_boundary import encode,decode

def main():
 idle();configure_runtime();out=ROOT/'artifacts/residual-representation-paired128';out.mkdir(exist_ok=False);source=ROOT/'artifacts/fresh-jepa-paired-first1024';cfg=json.loads((source/'config.json').read_text());items=json.loads((ROOT/'artifacts/jepa-route-balanced-train-audit/selection.json').read_text());train=[x['file'] for x in items if x['slot']!=2];dev=[x['file'] for x in items if x['slot']==2];assert set(train).isdisjoint(dev) and len(train)==84 and len(dev)==42;sel={'train':train,'validation':dev};(out/'selection.json').write_text(json.dumps(sel,indent=2));res=[]
 for p in train:
  with np.load(ROOT/'data/occ_v3'/p,allow_pickle=False) as a:
   xy=a['trajectory'][:,:2]*np.array([50,10]);prior=np.stack([float(a['state'][0])*30*np.arange(1,26)*.2,np.zeros(25)],-1);res.append(xy-prior)
 raw=np.quantile(abs(np.stack(res)),.9,axis=0);scales=np.maximum.accumulate(np.maximum(raw,[.5,.25]),axis=0);(out/'scale_calibration.json').write_text(json.dumps({'fit_windows':train,'quantile':.9,'floor_m':[.5,.25],'monotone':True,'raw_q90':raw.tolist(),'scales_m':scales.tolist(),'no_dev_or_test_fit':True},indent=2))
 # Tiny model verifies transforms only; same mixin used in full model.
 m=ResidualJEPA();m.set_scales(scales.tolist());b=batch_to([DiskSamples(train)[0],DiskSamples(train)[1]],'cpu');target=b['trajectory'];q=m.to_flow_space(b,target);back=m.from_flow_space(b,q);err=float((back-target).abs().max());assert err<1e-5
 poison={**b,'future':torch.full_like(b['future'],255),'trajectory':torch.full_like(target,999)};assert torch.equal(q,m.to_flow_space(poison,target));zero=torch.zeros_like(q);z=m.from_flow_space(b,zero);torch.testing.assert_close(z[...,:2]*torch.tensor([50,10]),m.prior(b));side=zero.clone();side[...,1]=1;assert ((m.from_flow_space(b,side)[...,1]-z[...,1])>0).all();assert (m.prior(b)[:,0,0]-b['state'][:,0]*30*.2).abs().max()<1e-6;(out/'tests.json').write_text(json.dumps({'roundtrip_max_abs':err,'future_label_poison_exact':True,'zero_residual_is_observed_v0_prior':True,'left_positive':True,'first_time_point_point2_seconds':True,'hard_initial_acceleration_bound':False},indent=2));del m,b,target,q,back,poison,zero,z,side
 results=[];startall=time.perf_counter()
 for seed in [1980,1981]:
  pl.seed_everything(seed,workers=True);initial=MaskedHistoryJoint(768,15,12);state={k:v.detach().clone() for k,v in initial.state_dict().items()};del initial;traces={};hashes={}
  for arm in (['original','residual'] if seed==1980 else ['residual','original']):
   idle();assert time.perf_counter()-startall<900;pl.seed_everything(seed,workers=True);folder=out/f'{seed}-{arm}';folder.mkdir();task=FreshTask(cfg,'fresh','residual-train-only',seed,'jepa')
   if arm=='residual':task.model=ResidualJEPA(768,15,12);task.model.set_scales(scales.tolist())
   task.model.load_state_dict(state,strict=True);assert all(torch.equal(v,state[k]) for k,v in task.model.state_dict().items());task.settings.update(representation=arm,residual_scale=scales.tolist() if arm=='residual' else None);status=Status(folder);torch.cuda.empty_cache();torch.cuda.reset_peak_memory_stats();start=time.perf_counter();tr=pl.Trainer(accelerator='gpu',devices=1,precision='bf16-mixed',max_steps=128,max_epochs=-1,max_time={'minutes':3},callbacks=[status,ModelCheckpoint(dirpath=str(folder),filename='step128',save_top_k=1,every_n_train_steps=128,save_on_train_epoch_end=False)],plugins=[VerifiedCheckpointIO()],logger=TensorBoardLogger(str(ROOT/'logs/tensorboard/v1'),name='residual-representation-paired128',version=f'{seed}-{arm}'),num_sanity_val_steps=0,limit_val_batches=0,gradient_clip_val=1,enable_progress_bar=False,enable_model_summary=False,log_every_n_steps=16);tr.fit(task,datamodule=SeedData(sel,seed));assert tr.global_step==128;wall=time.perf_counter()-start;peak=torch.cuda.max_memory_allocated()/2**30;traces[arm]=task.trace;hashes[arm]=status.hashes;(folder/'training_metadata.json').write_text(json.dumps({'grads':task.grads,'rng_trace':task.trace,'batch_hashes':status.hashes},indent=2));reference=copy.deepcopy(task.model.teacher).cuda().eval();ev=evaluate(task.model,dev,reference,True);ev['world_summary']={k:v for k,v in ev['world_summary'].items() if k.startswith('own_')};r={'seed':seed,'arm':arm,'steps':128,'wall_s':wall,'peak_allocated_gib':peak,'grad_clip_fraction':sum(x['clipped'] for x in task.grads)/len(task.grads),'eval':ev};(folder/'report.json').write_text(json.dumps(r,indent=2));brief={k:v for k,v in r.items() if k!='eval'};brief.update(metrics=ev['summary'],world=ev['world_summary']);results.append(brief);print('RESULT '+json.dumps(brief),flush=True);del task,tr,reference;gc.collect();torch.cuda.empty_cache()
  assert traces['original']==traces['residual'] and hashes['original']==hashes['residual'];del state;gc.collect()
 (out/'summary.json').write_text(json.dumps({'results':results,'wall_s':time.perf_counter()-startall,'paired_first3_rng_data':True,'limits':'128 updates ends at warmup peak; 84 train fit/opt windows42same-route other-slot diagnostic windows; overlap/route correlation; no test; not final driving quality; all previous weights preserved'},indent=2));print('DONE',flush=True)
if __name__=='__main__':main()
